<template><div class="page-card form-page" v-loading="loading"><div class="form-nav"><el-button :icon="ArrowLeft" @click="goBack">返回</el-button><span>{{isEdit?'编辑客户档案':'建立客户档案'}}</span></div><el-form ref="formRef" :model="form" :rules="rules" label-width="105px" class="customer-form"><section><header><span>基本信息</span><small>客户名称与日常联系方式</small></header><el-row :gutter="16"><el-col :span="12"><el-form-item label="客户名称" prop="name"><el-input v-model="form.name"/></el-form-item></el-col><el-col :span="6"><el-form-item label="联系人" prop="contact"><el-input v-model="form.contact"/></el-form-item></el-col><el-col :span="6"><el-form-item label="联系电话" prop="phone"><el-input v-model="form.phone"/></el-form-item></el-col></el-row><el-form-item label="联系地址"><el-input v-model="form.address"/></el-form-item></section><section><header><span>开票资料</span><small>用于开具发票和核对客户主体</small></header><el-form-item label="纳税人识别号"><el-input v-model="form.taxNo"/></el-form-item></section><section><header><span>银行账户</span><small>用于收款与资金核对</small></header><el-row :gutter="16"><el-col :span="12"><el-form-item label="开户银行"><el-input v-model="form.bankName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="银行账号"><el-input v-model="form.bankAccount"/></el-form-item></el-col></el-row></section><section><header><span>其他信息</span></header><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="3"/></el-form-item></section></el-form><footer><el-button @click="goBack">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存客户档案</el-button></footer></div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import type{FormInstance,FormRules}from'element-plus';import{ArrowLeft}from'@element-plus/icons-vue';import{merchantApi}from'../api';import type{Merchant}from'../types';const route=useRoute(),router=useRouter(),isEdit=computed(()=>!!route.params.id),loading=ref(false),saving=ref(false),formRef=ref<FormInstance>(),form=reactive<Partial<Merchant>>({});const rules:FormRules={name:[{required:true,message:'请输入客户名称',trigger:'blur'}],contact:[{required:true,message:'请输入联系人',trigger:'blur'}],phone:[{required:true,message:'请输入联系电话',trigger:'blur'}]};function reset(){Object.assign(form,{name:'',contact:'',phone:'',address:'',taxNo:'',bankName:'',bankAccount:'',remark:''})}function goBack(){router.push(isEdit.value?`/merchants/${route.params.id}`:'/merchants')}async function save(){await formRef.value?.validate();saving.value=true;try{let row:Merchant;if(isEdit.value)row=await merchantApi.update(Number(route.params.id),form);else row=await merchantApi.create(form);ElMessage.success('客户档案已保存');router.push(`/merchants/${row.id}`)}finally{saving.value=false}}onMounted(async()=>{reset();if(!isEdit.value)return;loading.value=true;try{const row=(await merchantApi.list()).find(item=>item.id===Number(route.params.id));if(row)Object.assign(form,row)}finally{loading.value=false}});
</script>
<style scoped>.form-page{max-width:1040px;margin:0 auto}.form-nav{display:flex;align-items:center;gap:14px;margin-bottom:18px;color:#526075}.customer-form{border:1px solid #dbe3ed}.customer-form section{padding:19px 22px 8px;border-bottom:1px solid #dbe3ed}.customer-form section:last-child{border-bottom:0}.customer-form header{display:flex;align-items:baseline;gap:12px;margin-bottom:17px;padding-left:10px;border-left:3px solid #16488a}.customer-form header span{color:#173b64;font-size:16px;font-weight:650}.customer-form header small{color:#7b8797}.form-page footer{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}</style>

